<?php
declare(strict_types=1);
date_default_timezone_set('America/Sao_Paulo');
final class Fault extends RuntimeException {public function __construct(string $message,public int $status=400){parent::__construct($message);}}
function uid():string{return bin2hex(random_bytes(16));}
function j($v):string{return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);}
function need($v,string $label,int $max=500):string{if(!is_string($v)||!trim($v)||mb_strlen(trim($v))>$max)throw new Fault('Confira '.$label.'.');return trim($v);}
function day($v,string $label='data'):string{$v=need($v,$label,10);$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);if(!$d||$d->format('Y-m-d')!==$v)throw new Fault('Data inválida: '.$label.'.');return $v;}
function today():string{return date('Y-m-d');}
function num($v,float $min,float $max,string $label):float{if(!is_numeric($v)||!is_finite((float)$v)||(float)$v<$min||(float)$v>$max)throw new Fault('Confira '.$label.'.');return (float)$v;}
function cpf($v):string{$s=preg_replace('/\D/','',(string)$v);if(strlen($s)!==11||preg_match('/^(\d)\1{10}$/',$s))throw new Fault('CPF inválido.');for($n=9;$n<11;$n++){$sum=0;for($i=0;$i<$n;$i++)$sum+=(int)$s[$i]*($n+1-$i);if(($sum*10)%11%10!==(int)$s[$n])throw new Fault('Dígitos verificadores do CPF inválidos.');}return $s;}
function config():array{static $c;return $c??=require TR_PRIVATE.'/config.php';}
function db():PDO{static $p;if(!$p){$c=config();$p=new PDO($c['dsn'],$c['db_user'],$c['db_password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);if($p->getAttribute(PDO::ATTR_DRIVER_NAME)==='sqlite')$p->exec('PRAGMA foreign_keys=ON');}return $p;}
function query(string $sql,array $args=[]):PDOStatement{$s=db()->prepare($sql);$s->execute($args);return $s;}
function one(string $sql,array $args=[]):?array{return query($sql,$args)->fetch()?:null;}
function seal(string $plain):string{$iv=random_bytes(12);$tag='';$cipher=openssl_encrypt($plain,'aes-256-gcm',base64_decode(config()['key']),OPENSSL_RAW_DATA,$iv,$tag,'trajetoria-v1');if($cipher===false)throw new Fault('Falha de criptografia.',500);return base64_encode($iv.$tag.$cipher);}
function unseal(string $data):string{$b=base64_decode($data,true);if($b===false||strlen($b)<28)throw new Fault('Registro protegido inválido.',500);$p=openssl_decrypt(substr($b,28),'aes-256-gcm',base64_decode(config()['key']),OPENSSL_RAW_DATA,substr($b,0,12),substr($b,12,16),'trajetoria-v1');if($p===false)throw new Fault('Não foi possível validar o registro protegido.',500);return $p;}
function records(string $tenant,string $kind):array{$rows=query('SELECT id,version,payload FROM tr_records WHERE tenant=? AND kind=? ORDER BY id',[$tenant,$kind])->fetchAll();return array_map(fn($r)=>array_replace(json_decode(unseal($r['payload']),true,512,JSON_THROW_ON_ERROR),['id'=>$r['id'],'version'=>(int)$r['version']]),$rows);}
function record(string $tenant,string $kind,string $id):?array{$r=one('SELECT version,payload FROM tr_records WHERE tenant=? AND kind=? AND id=?',[$tenant,$kind,$id]);return $r?array_replace(json_decode(unseal($r['payload']),true),['id'=>$id,'version'=>(int)$r['version']]):null;}
function save(string $tenant,string $kind,array $data,?int $expected=null):array{$id=$data['id']??uid();$old=record($tenant,$kind,$id);if($old){if($expected!==null&&$old['version']!==$expected)throw new Fault('Registro alterado por outra sessão. Atualize antes de salvar.',409);$version=$old['version']+1;unset($data['version']);$n=query('UPDATE tr_records SET payload=?,version=? WHERE tenant=? AND kind=? AND id=? AND version=?',[seal(j($data)),$version,$tenant,$kind,$id,$old['version']])->rowCount();if(!$n)throw new Fault('Registro alterado por outra sessão.',409);}else{$version=1;query('INSERT INTO tr_records(tenant,kind,id,version,payload) VALUES(?,?,?,?,?)',[$tenant,$kind,$id,1,seal(j($data))]);}return array_replace($data,['id'=>$id,'version'=>$version]);}
function audit(string $tenant,string $action,string $target):void{query('INSERT INTO tr_audit(id,tenant,actor,action,target,created) VALUES(?,?,?,?,?,?)',[uid(),$tenant,$_SESSION['uid']??'installer',$action,$target,date(DATE_ATOM)]);}
function txn(callable $fn){db()->beginTransaction();try{$v=$fn();db()->commit();return $v;}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}}
function lockTenant(string $tenant):void{if(db()->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql')query('SELECT id FROM tr_tenants WHERE id=? FOR UPDATE',[$tenant]);}
function fullManager(array $u):void{if($u['role']!=='admin'||$u['unit']||$u['power'])throw new Fault('Somente o Gestor Municipal pode executar esta operação.',403);}
function platformOwner(array $u):void{if($u['role']!=='platform'||$u['is_demo'])throw new Fault('Administração da instalação restrita ao administrador real.',403);}
function canScope(array $u,array $link):bool{return (!$u['unit']||$u['unit']===$link['unitId'])&&(!$u['power']||$u['power']===$link['power']);}
function visibleLink(array $u,array $p):bool{if($u['role']==='employee')return $u['person']===$p['personId'];if($u['role']==='commission'){if($u['person']===$p['personId'])return true;foreach(records($u['tenant'],'appointments') as $a)if(reviewerAllowed($u,$a,$p))return true;return false;}return canScope($u,$p);}
function auth():array{$id=$_SESSION['uid']??'';$u=$id?one('SELECT * FROM tr_users WHERE id=?',[$id]):null;if(!$u||!$u['active']||(int)$u['auth_epoch']!==($_SESSION['epoch']??-1)||time()-($_SESSION['at']??0)>1800||time()-($_SESSION['started']??0)>28800||$u['is_demo']&&(!config()['demo_enabled']||$u['demo_until']<today())){$_SESSION=['csrf'=>bin2hex(random_bytes(32))];throw new Fault('Entre com sua conta para continuar.',401);}$_SESSION['at']=time();if($u['must_change']&&parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH)!=='/api/auth/password')throw new Fault('Defina sua senha pessoal para continuar.',428);return $u;}
function csrf():void{$expected=$_SESSION['csrf']??null;$provided=$_SERVER['HTTP_X_CSRF_TOKEN']??null;if(!is_string($expected)||!is_string($provided)||$expected===''||$provided===''||!hash_equals($expected,$provided))throw new Fault('Sessão de formulário expirada. Recarregue a página.',403);$origin=$_SERVER['HTTP_ORIGIN']??'';if($origin&&$origin!==config()['url'])throw new Fault('Origem não autorizada.',403);}
function requestBody():array{$raw=file_get_contents('php://input',false,null,0,2097153);if(strlen($raw)>2097152)throw new Fault('Conteúdo muito grande.',413);try{$b=json_decode($raw?:'{}',true,64,JSON_THROW_ON_ERROR);}catch(Throwable){throw new Fault('JSON inválido.');}if(!is_array($b)||array_is_list($b)&&$b)throw new Fault('Requisição inválida.');return $b;}
function reply($data,int $status=200):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');echo j($data);exit;}
function secureHeaders():void{header('Cache-Control: no-store, private, max-age=0');header('Pragma: no-cache');header('Expires: 0');header('X-Content-Type-Options: nosniff');header('X-Frame-Options: SAMEORIGIN');header('Referrer-Policy: same-origin');header("Content-Security-Policy: default-src 'self'; script-src 'self' 'unsafe-inline' 'wasm-unsafe-eval'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; font-src 'self'; connect-src 'self'; worker-src 'self' blob:; frame-src 'self' blob:; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'self'");if(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')header('Strict-Transport-Security: max-age=31536000');}
function userPublic(array $u):array{return ['id'=>$u['id'],'email'=>$u['email'],'role'=>$u['role'],'power'=>$u['power'],'unit'=>$u['unit'],'person'=>$u['person'],'subject'=>$u['id'],'active'=>(bool)$u['active'],'isDemo'=>(bool)$u['is_demo']];}
function newUser(string $tenant,string $email,string $name,string $role,?string $person=null,?string $unit=null,?string $power=null,bool $demo=false,?string $password=null,?string $cpf=null):array{if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new Fault('E-mail inválido.');if(!in_array($role,['platform','admin','manager','viewer','employee','commission'],true))throw new Fault('Perfil inválido.');$id=uid();$password??=bin2hex(random_bytes(12)).'aA!';query('INSERT INTO tr_users(id,tenant,email,name,role,person,unit,power,password_hash,cpf_hash,active,is_demo,demo_until,must_change,auth_epoch) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$id,$tenant?:null,strtolower($email),$name,$role,$person,$unit,$power,password_hash($password,PASSWORD_DEFAULT),$cpf?hash_hmac('sha256',cpf($cpf),config()['key']):null,1,$demo?1:0,$demo?date('Y-m-d',strtotime('+30 days')):null,$demo?0:1,1]);return ['id'=>$id,'temporaryPassword'=>$password];}
function passwordRules(string $p):void{if(strlen($p)<14||strlen($p)>128||!preg_match('/[a-z]/',$p)||!preg_match('/[A-Z]/',$p)||!preg_match('/\d/',$p))throw new Fault('Use uma senha de 14 a 128 caracteres, com letras maiúsculas, minúsculas e números.');}
